solution.solution.cpp:
#include <cstdint>

// How many pages of pageSize bytes are needed to hold bytes bytes.
std::uint64_t pagesNeeded(std::uint64_t bytes, std::uint64_t pageSize)
{
    return (bytes + pageSize - 1) / pageSize;
}

// The number of bytes reserved: bytes rounded up to a whole number of pages.
std::uint64_t roundUpToPage(std::uint64_t bytes, std::uint64_t pageSize)
{
    return pagesNeeded(bytes, pageSize) * pageSize;
}

unitTests:
TEST("nothing needs nothing") { CHECK_EQ(pagesNeeded(0, 4096), 0ull); CHECK_EQ(roundUpToPage(0, 4096), 0ull); }
TEST("one byte costs a page") { CHECK_EQ(pagesNeeded(1, 4096), 1ull); CHECK_EQ(roundUpToPage(1, 4096), 4096ull); }
TEST("exactly one page") { CHECK_EQ(pagesNeeded(4096, 4096), 1ull); }
TEST("one byte over") { CHECK_EQ(pagesNeeded(4097, 4096), 2ull); CHECK_EQ(roundUpToPage(4097, 4096), 8192ull); }
TEST("the example") { CHECK_EQ(roundUpToPage(5000, 4096), 8192ull); }
TEST("a large allocation") { CHECK_EQ(pagesNeeded(10'000'000, 4096), 2442ull); }
TEST("other page sizes") { CHECK_EQ(pagesNeeded(65537, 65536), 2ull); CHECK_EQ(roundUpToPage(3, 2), 4ull); }

